mapper.query:
query ProductSync {
  products(first: 50, query: "-bundles:true AND -tag:'access:exclusive'") {
    pageInfo { hasNextPage }
    nodes {
      id
      title
      productType
      tags
      variants(first: 50) {
        pageInfo { hasNextPage }
        nodes {
          id
          sku
          title
          price
          inventoryItem { unitCost { amount } }
        }
      }
    }
  }
}

mapper.codeEditorJavascript:
// Baut die ctx-Nutzlast als fertigen JSON-Text. Eine Fehlermeldung kann
// Anfuehrungszeichen und Zeilenumbrueche tragen — roh in einen
// JSON-String-Body gesetzt wuerde sie die Nutzlast zerlegen.
return { ctx: JSON.stringify({
  'Szenario': "[Sync] Shopify Products to Airtable",
  'Stufe': "Shopify lesen (GraphQL)",
  'Fehler': String(input.fehler || 'unbekannt'),
  'Folge': "keine Produkte, Varianten oder Preise abgeglichen"
}) };

// Produkt-Ebene. Match ueber ⚙ Shopify GID, nicht ueber ID.
// Liefert Zeilen-Arrays; geschrieben wird pro Datensatz ueber die nativen
// Airtable-Module (Create/Update), weil das API-Call-Modul mit Body nicht
// traegt. Ein Datensatz je Operation — bei woechentlichem Takt irrelevant.
// ID wird ausschliesslich beim Anlegen gesetzt, Form <Nummer>-000.
const F_ID = 'fldglRrcSpfvq4ySR';
const F_NAME = 'fldZa1wmLlTenikuC';
const F_TYP = 'fldKkreKUYX5WuLoW';
const F_TAGS = 'fldWyNQ07Mh6Xcpgg';
const F_GID = 'fld2a7MGVts13AEeW';

// Typ ist ein SingleSelect. Es wird ohne typecast geschrieben, damit kein
// unbekannter productType still eine neue Option anlegt — deshalb hier die
// Liste explizit fuehren statt sich auf die API-Strenge zu verlassen.
const TYP_OPTIONEN = ['Kratom', 'POS Display'];
const PAGE_LIMIT = 100;
const GID_RE = /^gid:\/\/shopify\/Product\/[0-9]{10,}$/;

function splitSku(sku) {
  if (typeof sku !== 'string') return null;
  const s = sku.trim();
  const i = s.lastIndexOf('-');
  if (i <= 0 || i === s.length - 1) return null;
  return { product: s.slice(0, i), variant: s.slice(i + 1), sku: s };
}
function sameText(a, b) {
  return String(a === null || a === undefined ? '' : a) === String(b === null || b === undefined ? '' : b);
}

const { shopify, hasNextPage, produkte } = input;
const nodes = Array.isArray(shopify) ? shopify : [];
const bestand = Array.isArray(produkte) ? produkte : [];
const notes = [];
const skipped = [];

if (String(hasNextPage) === 'true') {
  notes.push('Shopify meldet hasNextPage — der Katalog ist ueber 50 Produkte gewachsen, die Abfrage ist unvollstaendig.');
}
if (bestand.length >= PAGE_LIMIT) {
  notes.push('Produkte NEU hat die Seitengrenze erreicht — Pagination noetig.');
}

const byGid = {};
const gidSeen = {};
const poisoned = {};
const byId = {};
for (let i = 0; i < bestand.length; i++) {
  const f = bestand[i].fields || {};
  const id = f[F_ID];
  if (typeof id === 'string' && id !== '') byId[id] = bestand[i].id;
  const gid = f[F_GID];
  if (typeof gid !== 'string' || gid === '') continue;
  if (!GID_RE.test(gid)) {
    notes.push('Produkt ' + String(id || bestand[i].id) + ': ⚙ Shopify GID "' + gid + '" ist keine gueltige Product-GID — Zeile wird nicht ueber GID gefunden.');
    continue;
  }
  gidSeen[gid] = (gidSeen[gid] || 0) + 1;
  if (gidSeen[gid] > 1) poisoned[gid] = true;
  byGid[gid] = { recId: bestand[i].id, fields: f };
}
const poisonList = Object.keys(poisoned);
for (let i = 0; i < poisonList.length; i++) {
  notes.push('⚙ Shopify GID ' + poisonList[i] + ' liegt auf ' + gidSeen[poisonList[i]] + ' Produktzeilen — mehrdeutig, betroffene Produkte werden nicht angefasst.');
}

const creates = [];
const updates = [];
const seenNumber = {};

for (let i = 0; i < nodes.length; i++) {
  const p = nodes[i];
  const gid = String(p.id || '');
  const vlist = p.variants && Array.isArray(p.variants.nodes) ? p.variants.nodes : [];
  let nr = null;
  for (let j = 0; j < vlist.length; j++) {
    const parts = splitSku(vlist[j].sku);
    if (parts) { nr = parts.product; break; }
  }
  const name = String(p.title || '');
  if (!nr) { skipped.push(name + ': keine auswertbare SKU'); continue; }
  if (seenNumber[nr]) { skipped.push(name + ': Produktnummer ' + nr + ' doppelt belegt'); continue; }
  seenNumber[nr] = true;
  if (poisoned[gid]) { skipped.push(name + ': GID mehrdeutig in Airtable'); continue; }

  const typ = String(p.productType || '');
  if (TYP_OPTIONEN.indexOf(typ) === -1) {
    skipped.push(name + ': productType "' + typ + '" ist keine bekannte Typ-Option — nicht geschrieben.');
    continue;
  }

  const nummer = nr + '-000';
  const tags = Array.isArray(p.tags) ? p.tags.join(', ') : '';
  const hit = byGid[gid];

  if (hit) {
    const cur = hit.fields;
    if (!sameText(cur[F_ID], nummer)) {
      notes.push('Produkt ' + String(cur[F_ID] || '') + ': ID weicht von der erwarteten Form ' + nummer + ' ab — ID wird im Update nie geschrieben, bitte pruefen.');
    }
    const changed = !sameText(cur[F_NAME], name) || !sameText(cur[F_TYP], typ) || !sameText(cur[F_TAGS], tags);
    if (changed) updates.push({ recId: hit.recId, name: name, typ: typ, tags: tags });
    continue;
  }

  if (byId[nummer]) {
    skipped.push(name + ': ID ' + nummer + ' existiert bereits, aber ohne passende GID — nicht angelegt, GID pruefen.');
    continue;
  }
  creates.push({ nummer: nummer, name: name, typ: typ, tags: tags, gid: gid });
}

return {
  productCreates: creates,
  productUpdates: updates,
  hasProductCreate: creates.length > 0 ? '1' : '',
  hasProductUpdate: updates.length > 0 ? '1' : '',
  productCreateCount: String(creates.length),
  productUpdateCount: String(updates.length),
  productTotal: String(nodes.length),
  notesJson: JSON.stringify(notes),
  skippedJson: JSON.stringify(skipped)
};

// Varianten-Ebene. Match ueber ⚙ Shopify GID.
// ID (= volle SKU) traegt den Bestandsschluessel und steht ausschliesslich im
// Anlege-Payload — der Update-Mapper kennt das Feld gar nicht.
// ⚙ EK (netto) ist ein SPIEGEL des aktuellen unitCost, kein Stempel.
const F_P_GID = 'fld2a7MGVts13AEeW';
const F_V_ID = 'flduzOEUi4iJGmqmw';
const F_V_VAR = 'flddoYJ4b0WsDAcYh';
const F_V_PROD = 'fld0KMcyfc7pSJupr';
const F_V_EK = 'fldjVBRtbovK3Ky92';
const F_V_GID = 'fldtyjDFiy2DoFRNN';

const PAGE_LIMIT = 100;
const P_GID_RE = /^gid:\/\/shopify\/Product\/[0-9]{10,}$/;
const V_GID_RE = /^gid:\/\/shopify\/ProductVariant\/[0-9]{10,}$/;

function splitSku(sku) {
  if (typeof sku !== 'string') return null;
  const s = sku.trim();
  const i = s.lastIndexOf('-');
  if (i <= 0 || i === s.length - 1) return null;
  return { product: s.slice(0, i), variant: s.slice(i + 1), sku: s };
}
function num(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function sameText(a, b) {
  return String(a === null || a === undefined ? '' : a) === String(b === null || b === undefined ? '' : b);
}
function sameMoney(a, b) {
  const x = num(a), y = num(b);
  if (x === null && y === null) return true;
  if (x === null || y === null) return false;
  return Math.round(x * 100) === Math.round(y * 100);
}
function sameLink(cur, wantId) {
  const arr = Array.isArray(cur) ? cur : [];
  return arr.length === 1 && arr[0] === wantId;
}

const { shopify, produkteBestand, produkteNeu, variantenBestand } = input;
const nodes = Array.isArray(shopify) ? shopify : [];
const vBestand = Array.isArray(variantenBestand) ? variantenBestand : [];
const notes = [];
const skipped = [];

if (vBestand.length >= PAGE_LIMIT) {
  notes.push('Produktvarianten hat die Seitengrenze erreicht — Pagination noetig.');
}

// Produkt-recordIds ueber die Produkt-GID. Frisch angelegte Produkte kommen
// als aggregiertes Ergebnis der Anlege-Schleife herein.
const prodByGid = {};
const bestandList = Array.isArray(produkteBestand) ? produkteBestand : [];
for (let i = 0; i < bestandList.length; i++) {
  const g = (bestandList[i].fields || {})[F_P_GID];
  if (typeof g === 'string' && P_GID_RE.test(g)) prodByGid[g] = bestandList[i].id;
}
const neuList = Array.isArray(produkteNeu) ? produkteNeu : [];
for (let i = 0; i < neuList.length; i++) {
  const g = neuList[i].gid;
  const r = neuList[i].recId;
  if (typeof g === 'string' && P_GID_RE.test(g) && typeof r === 'string' && r !== '') prodByGid[g] = r;
}

const byGid = {};
const gidSeen = {};
const poisoned = {};
const bySku = {};
for (let i = 0; i < vBestand.length; i++) {
  const f = vBestand[i].fields || {};
  const sku = f[F_V_ID];
  if (typeof sku === 'string' && sku !== '') bySku[sku] = vBestand[i].id;
  const gid = f[F_V_GID];
  if (typeof gid !== 'string' || gid === '') continue;
  if (!V_GID_RE.test(gid)) {
    notes.push('Variante ' + String(sku || vBestand[i].id) + ': ⚙ Shopify GID "' + gid + '" ist keine gueltige Variant-GID — Zeile wird nicht ueber GID gefunden.');
    continue;
  }
  gidSeen[gid] = (gidSeen[gid] || 0) + 1;
  if (gidSeen[gid] > 1) poisoned[gid] = true;
  byGid[gid] = { recId: vBestand[i].id, fields: f };
}
const poisonList = Object.keys(poisoned);
for (let i = 0; i < poisonList.length; i++) {
  notes.push('⚙ Shopify GID ' + poisonList[i] + ' liegt auf ' + gidSeen[poisonList[i]] + ' Variantenzeilen — mehrdeutig, betroffene Varianten werden nicht angefasst.');
}

const creates = [];
const updates = [];
const seenSku = {};
let total = 0;

for (let i = 0; i < nodes.length; i++) {
  const p = nodes[i];
  const pGid = String(p.id || '');
  const vl = p.variants && Array.isArray(p.variants.nodes) ? p.variants.nodes : [];
  // Der Katalog-Wächter greift auch je Produkt: mehr als 50 Varianten wuerden
  // still fehlen und als "nicht in Shopify" durchgehen.
  if (p.variants && p.variants.pageInfo && String(p.variants.pageInfo.hasNextPage) === 'true') {
    notes.push(String(p.title || '') + ': mehr als 50 Varianten in Shopify — Variantenabfrage unvollstaendig.');
  }
  for (let j = 0; j < vl.length; j++) {
    const v = vl[j];
    const gid = String(v.id || '');
    const parts = splitSku(v.sku);
    if (!parts) { skipped.push(String(p.title || '') + ' / ' + String(v.title || '') + ': SKU nicht auswertbar'); continue; }
    total++;
    const label = parts.sku + ' · ' + String(p.title || '') + ' ' + String(v.title || '');
    if (seenSku[parts.sku]) { skipped.push(label + ': SKU doppelt im Katalog'); continue; }
    seenSku[parts.sku] = true;
    if (poisoned[gid]) { skipped.push(label + ': GID mehrdeutig in Airtable'); continue; }
    if (!V_GID_RE.test(gid)) { skipped.push(label + ': Shopify liefert keine gueltige Variant-GID'); continue; }

    const prodRec = prodByGid[pGid];
    if (!prodRec) { skipped.push(label + ': kein Produkt-Datensatz zur Produkt-GID'); continue; }

    const ek = num(v.inventoryItem && v.inventoryItem.unitCost ? v.inventoryItem.unitCost.amount : null);
    if (ek === null) notes.push(label + ': Shopify fuehrt keinen unitCost — ⚙ EK (netto) bleibt leer.');
    const variante = String(v.title || '');
    const ekOut = ek === null ? '' : ek;

    const hit = byGid[gid];
    if (hit) {
      const cur = hit.fields;
      // SKU-Drift: die Zeile traegt den Bestandsschluessel. Weicht sie ab,
      // bleibt sie unangetastet — ID im Update zu schreiben waere genau der
      // stille Bruch, den die Feldbeschreibung verbietet.
      if (!sameText(cur[F_V_ID], parts.sku)) {
        skipped.push(label + ': Airtable fuehrt diese GID unter ID "' + String(cur[F_V_ID] || '') + '" — SKU-Drift, Zeile nicht angefasst.');
        continue;
      }
      const changed = !sameText(cur[F_V_VAR], variante) || !sameMoney(cur[F_V_EK], ek) || !sameLink(cur[F_V_PROD], prodRec);
      if (changed) updates.push({ recId: hit.recId, variante: variante, produkt: prodRec, ek: ekOut, sku: parts.sku });
      continue;
    }

    if (bySku[parts.sku]) {
      skipped.push(label + ': SKU existiert bereits, aber ohne passende GID — nicht angelegt, GID pruefen.');
      continue;
    }
    creates.push({ sku: parts.sku, variante: variante, produkt: prodRec, ek: ekOut, gid: gid });
  }
}

return {
  variantCreates: creates,
  variantUpdates: updates,
  hasVariantCreate: creates.length > 0 ? '1' : '',
  hasVariantUpdate: updates.length > 0 ? '1' : '',
  variantCreateCount: String(creates.length),
  variantUpdateCount: String(updates.length),
  variantTotal: String(total),
  notesJson: JSON.stringify(notes),
  skippedJson: JSON.stringify(skipped)
};

// Preis-Ebene. Append-only: eine Abweichung erzeugt einen NEUEN Datensatz,
// nie ein Update auf einen bestehenden — sonst rechnet die Historie nach.
// Verglichen wird BRUTTO gegen BRUTTO auf 2 Nachkommastellen, gegen den
// juengsten Preis mit Gueltig ab <= heute.
//
// Geschluesselt wird ueber den VARIANTENLINK (fldCdNn8nWUcgPlFG), nicht ueber
// eine Artikelnummer: Preise haengt seit der Umstellung direkt an
// Produktvarianten, das alte Lookup-Feld existiert nicht mehr. Der Link
// liefert recordIds — die SKU kommt aus dem frischen Variantenlesen.
const F_PR_VAR = 'fldCdNn8nWUcgPlFG';
const F_PR_AB = 'fldI7FiSfUxmDxNNj';
const F_PR_VK = 'fldrvbwTvTBGatH9M';
const F_PR_STEUER = 'fld2CqRpUPtXmtg5t';
const F_PR_UMSATZPOS = 'fldU1uDEOoNvrj1CY';
const F_PR_LIEFERPOS = 'fldoFc0cajTjg8wbz';
const F_V_ID = 'flduzOEUi4iJGmqmw';
const F_ST_AB = 'flda8dLWKeYOfHk9x';

const PAGE_LIMIT = 100;

function splitSku(sku) {
  if (typeof sku !== 'string') return null;
  const s = sku.trim();
  const i = s.lastIndexOf('-');
  if (i <= 0 || i === s.length - 1) return null;
  return s;
}
function num(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function cents(v) {
  const n = num(v);
  return n === null ? null : Math.round(n * 100);
}
function firstLookup(v) {
  if (Array.isArray(v)) return v.length > 0 ? v[0] : null;
  return v === undefined ? null : v;
}
function dateOnly(v) {
  if (typeof v !== 'string') return '';
  return v.slice(0, 10);
}
function linkCount(v) { return Array.isArray(v) ? v.length : 0; }

const { shopify, preise, preiseMehr, offset1, varianten, steuersaetze, today } = input;
const nodes = Array.isArray(shopify) ? shopify : [];
const heute = dateOnly(String(today || ''));
const notes = [];
const alarms = [];
const creates = [];
const updates = [];
const changes = [];

if (heute.length !== 10) notes.push('Datum konnte nicht gebildet werden — Preislauf uebersprungen.');

// Varianten: recordId <-> SKU in beide Richtungen. Links kommen als recordId
// herein, geschrieben wird ebenfalls als recordId.
const varList = Array.isArray(varianten) ? varianten : [];
if (varList.length >= PAGE_LIMIT) {
  notes.push('Produktvarianten hat die Seitengrenze erreicht — Preislauf unvollstaendig.');
}
const skuByRec = {};
const recBySku = {};
for (let i = 0; i < varList.length; i++) {
  const sku = (varList[i].fields || {})[F_V_ID];
  if (typeof sku !== 'string' || sku === '') continue;
  skuByRec[varList[i].id] = sku;
  recBySku[sku] = varList[i].id;
}

// Preise kommen in zwei Teilen herein: Seite 1 aus dem Direktlesen, Seite 2..n
// aus der Offset-Schleife. Zusammenfuehren und ueber die recordId entdoppeln —
// ein doppelt gelesener Datensatz wuerde sonst als eigene Preisversion zaehlen.
const preisList = [];
const gesehen = {};
function addPreise(list) {
  const arr = Array.isArray(list) ? list : [];
  for (let i = 0; i < arr.length; i++) {
    const r = arr[i];
    if (!r || typeof r.id !== 'string' || gesehen[r.id]) continue;
    gesehen[r.id] = true;
    preisList.push(r);
  }
}
addPreise(preise);

let restOffset = '';
const extra = Array.isArray(preiseMehr) ? preiseMehr : [];
for (let i = 0; i < extra.length; i++) {
  const seite = extra[i] || {};
  addPreise(seite.records);
  restOffset = (typeof seite.offset === 'string' && seite.offset !== '') ? seite.offset : '';
}
const seite1Offset = String(offset1 === null || offset1 === undefined ? '' : offset1);

// Drei Zustaende, in denen der Preisbestand nachweislich unvollstaendig ist.
// Alle drei ueberspringen den Preislauf, statt auf halber Datenlage zu rechnen.
let leseFehler = '';
if (preisList.length === 0) {
  leseFehler = 'Preise-Lesen lieferte 0 Zeilen — Lesefehler wahrscheinlich, Preislauf uebersprungen.';
} else if (restOffset) {
  leseFehler = 'Preise: Offset-Schleife nach ' + preisList.length + ' Zeilen ausgelaufen — Repeater-Durchlaeufe erhoehen, Preislauf uebersprungen.';
} else if (seite1Offset && extra.length === 0) {
  leseFehler = 'Preise: Seite 1 meldet weitere Seiten, die Offset-Schleife hat aber nichts geliefert — Preislauf uebersprungen.';
}
if (leseFehler) alarms.push(leseFehler);

// Alle Preise EINMAL indizieren statt pro Variante zu suchen.
const byArtikel = {};
let ohneVariante = 0;
for (let i = 0; i < preisList.length; i++) {
  const f = preisList[i].fields || {};
  const ref = firstLookup(f[F_PR_VAR]);
  const art = typeof ref === 'string' ? skuByRec[ref] : null;
  if (!art) { ohneVariante++; continue; }
  if (!byArtikel[art]) byArtikel[art] = [];
  byArtikel[art].push({
    id: preisList[i].id,
    ab: dateOnly(f[F_PR_AB]),
    vk: cents(f[F_PR_VK]),
    steuer: firstLookup(f[F_PR_STEUER]),
    positionen: linkCount(f[F_PR_UMSATZPOS]) + linkCount(f[F_PR_LIEFERPOS])
  });
}
if (ohneVariante > 0) {
  notes.push(ohneVariante + ' Preiszeile(n) ohne aufloesbare Variante — beim Abgleich ignoriert.');
}

let fallbackSteuer = null;
let bestAb = '';
const stList = Array.isArray(steuersaetze) ? steuersaetze : [];
for (let i = 0; i < stList.length; i++) {
  const ab = dateOnly((stList[i].fields || {})[F_ST_AB]);
  if (ab && ab <= heute && ab >= bestAb) { bestAb = ab; fallbackSteuer = stList[i].id; }
}

if (heute.length === 10 && !leseFehler) {
  for (let i = 0; i < nodes.length; i++) {
    const p = nodes[i];
    const vl = p.variants && Array.isArray(p.variants.nodes) ? p.variants.nodes : [];
    for (let j = 0; j < vl.length; j++) {
      const v = vl[j];
      const sku = splitSku(v.sku);
      if (!sku) continue;
      const label = sku + ' · ' + String(p.title || '') + ' ' + String(v.title || '');
      const soll = cents(v.price);
      if (soll === null) { notes.push(label + ': Shopify liefert keinen auswertbaren Preis.'); continue; }

      const list = byArtikel[sku] || [];
      let aktuell = null;
      let zukunft = 0;
      for (let k = 0; k < list.length; k++) {
        if (!list[k].ab) continue;
        if (list[k].ab <= heute) {
          if (aktuell === null || list[k].ab > aktuell.ab) aktuell = list[k];
        } else {
          zukunft++;
        }
      }
      // Ein datierter Zukunftspreis ist eine bewusste Planung. Ein zweiter
      // Datensatz ab heute wuerde sie ueberlagern statt ersetzen.
      if (zukunft > 0) {
        alarms.push(label + ': ' + zukunft + ' Preis(e) mit Gueltig ab in der Zukunft — Variante uebersprungen.');
        continue;
      }

      if (aktuell === null) {
        const varId = recBySku[sku];
        if (!varId) { notes.push(label + ': keine Variantenzeile fuer den Erstpreis.'); continue; }
        if (!fallbackSteuer) { notes.push(label + ': kein gueltiger Steuersatz fuer den Erstpreis.'); continue; }
        creates.push({ ab: heute, vk: soll / 100, steuer: fallbackSteuer, variante: varId, label: label });
        changes.push(label + ': Erstpreis ' + (soll / 100).toFixed(2) + ' €');
        continue;
      }

      if (aktuell.vk === soll) continue;

      const alteAnzeige = aktuell.vk === null ? '—' : (aktuell.vk / 100).toFixed(2);
      const neueAnzeige = (soll / 100).toFixed(2);

      if (aktuell.ab === heute) {
        if (aktuell.positionen > 0) {
          alarms.push(label + ': Preis von heute haengt bereits an ' + aktuell.positionen + ' Position(en) — nicht geaendert (' + alteAnzeige + ' € statt ' + neueAnzeige + ' €).');
        } else {
          updates.push({ recId: aktuell.id, vk: soll / 100, label: label });
          changes.push(label + ': heutiger Preis korrigiert ' + alteAnzeige + ' € → ' + neueAnzeige + ' €');
        }
        continue;
      }

      const varId = recBySku[sku];
      if (!varId) {
        notes.push(label + ': keine Variantenzeile — neuer Preis uebersprungen, der Datensatz waere ohne Verknuepfung.');
        continue;
      }
      if (!aktuell.steuer) {
        notes.push(label + ': Vorgaengerpreis hat keinen Steuersatz — neuer Preis uebersprungen.');
        continue;
      }
      creates.push({ ab: heute, vk: soll / 100, steuer: aktuell.steuer, variante: varId, label: label });
      changes.push(label + ': ' + alteAnzeige + ' € → ' + neueAnzeige + ' € (ab ' + heute + ')');
    }
  }
}

return {
  priceCreates: creates,
  priceUpdates: updates,
  hasPriceCreate: creates.length > 0 ? '1' : '',
  hasPriceUpdate: updates.length > 0 ? '1' : '',
  priceCreateCount: String(creates.length),
  priceUpdateCount: String(updates.length),
  changesJson: JSON.stringify(changes),
  alarmsJson: JSON.stringify(alarms),
  notesJson: JSON.stringify(notes)
};

// Report fuer den Operations-Channel.
// Bestaetigt wird ueber die von Airtable zurueckgegebenen Record-IDs, nicht
// ueber einen HTTP-Status: eine ID ist der Beweis, dass die Zeile existiert.
// Fehlt sie, steht das als Schreibfehler da — nie als Erfolg.
function parseList(v) {
  if (Array.isArray(v)) return v;
  if (typeof v !== 'string' || v.trim() === '') return [];
  try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
}
function n(v) {
  const x = Number(String(v === null || v === undefined ? '0' : v).trim());
  return Number.isFinite(x) ? x : 0;
}
function countIds(v) {
  const raw = String(v === null || v === undefined ? '' : v).trim();
  if (raw === '') return 0;
  return raw.split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s !== ''; }).length;
}
function block(lines, title, items) {
  if (!items.length) return;
  lines.push('');
  lines.push(title);
  for (let i = 0; i < items.length; i++) lines.push('• ' + items[i]);
}

const {
  productTotal, variantTotal,
  productCreateCount, productUpdateCount, variantCreateCount, variantUpdateCount,
  priceCreateCount, priceUpdateCount,
  productCreateIds, productUpdateIds, variantCreateIds, variantUpdateIds,
  priceCreateIds, priceUpdateIds,
  notesA, notesB, notesC, skippedA, skippedB,
  changes, alarms
} = input;

const writeErrors = [];
function confirmed(label, planned, ids) {
  const p = n(planned);
  if (p === 0) return 0;
  const ok = countIds(ids);
  if (ok < p) {
    writeErrors.push(label + ': ' + ok + ' von ' + p + ' bestaetigt — ' + (p - ok) + ' ohne Record-ID zurueck');
  }
  return ok;
}

const pc = confirmed('Produkte anlegen', productCreateCount, productCreateIds);
const pu = confirmed('Produkte ändern', productUpdateCount, productUpdateIds);
const vc = confirmed('Varianten anlegen', variantCreateCount, variantCreateIds);
const vu = confirmed('Varianten ändern', variantUpdateCount, variantUpdateIds);
const qc = confirmed('Preise anlegen', priceCreateCount, priceCreateIds);
const qu = confirmed('Preise korrigieren', priceUpdateCount, priceUpdateIds);

function part(ok, plan, wort) {
  const p = n(plan);
  return ok + ' ' + wort + (ok !== p ? ' (von ' + p + ' geplant)' : '');
}

const notes = parseList(notesA).concat(parseList(notesB)).concat(parseList(notesC));
const skipped = parseList(skippedA).concat(parseList(skippedB));
const chg = parseList(changes);
const alr = parseList(alarms);

const head = (alr.length || writeErrors.length || skipped.length) ? '⚠️ Produkt-Sync' : '✅ Produkt-Sync';
const L = [head, ''];
L.push('Produkte: ' + String(productTotal || '0') + ' gelesen · ' + part(pc, productCreateCount, 'angelegt') + ' · ' + part(pu, productUpdateCount, 'geändert'));
L.push('Varianten: ' + String(variantTotal || '0') + ' gelesen · ' + part(vc, variantCreateCount, 'angelegt') + ' · ' + part(vu, variantUpdateCount, 'geändert'));
L.push('Preise: ' + part(qc, priceCreateCount, 'neu') + ' · ' + part(qu, priceUpdateCount, 'korrigiert'));

block(L, 'Preisänderungen:', chg);
block(L, '⚠️ Preis-Alarme:', alr);
block(L, '⚠️ Übersprungen:', skipped);
block(L, 'Hinweise:', notes);
block(L, '⚠️ Schreibfehler:', writeErrors);

// Zaehlwerte fuer die Landkarten-Vorlage sync.products, fertig als ctx-JSON.
// Der Fliesstext bleibt als text erhalten, wird aber nicht mehr gepostet.
return {
  text: L.join('\n'),
  ctx: JSON.stringify({
    n: String(productTotal || 0), m: String(variantTotal || 0),
    a: String(pc), b: String(pu), c: String(vc), d: String(vu), e: String(qu)
  })
};
